#define MAXDIST 10.f
#define MAXSTEP 128
#define minDist .0001

struct Ray
{
    vec3 ro;
    vec3 rd;
};

//https://iquilezles.org/articles/distfunctions/
float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}
float sdBox( vec3 p, vec3 b )
{
  //width,height,longth
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

//https://iquilezles.org/articles/distfunctions/
float opU( float d1, float d2 )
{
    return min(d1,d2);
}


//combination
float map(in vec3 pos)
{
    //closest edge found, init as small number for a reason idk, thank you IQ
    float ce = pos.y;

    vec3 q = pos - vec3(sin(iTime),.0,cos(iTime));

    //vec3 repeat = opRepetition(pos,vec3(2.,5.,2.));

    ce = opU(sdSphere(q,.1),sdSphere(pos,.5));



    return ce;
}

//https://iquilezles.org/articles/normalsSDF/
vec3 calcNormal( in vec3 pos ){

    vec2 e = vec2(1.0,-1.0)*0.3108*0.0005;
    return normalize( e.xyy*map( pos + e.xyy ) + 
					  e.yyx*map( pos + e.yyx ) + 
					  e.yxy*map( pos + e.yxy ) + 
					  e.xxx*map( pos + e.xxx ) );

}

vec3 getColor(in vec3 rd){

    vec3 ro = vec3(.0,0.,-2.+sin(iTime));
    //take the dist to an edge then multiply with the normalized rd
    rd -= vec3(.0 ,.0,.1);


    float distToEdge = map(rd);

    float distTraveled = 0.;

    float smallest = 1.;

    for(int i = 0; i < MAXSTEP; i++){
        //ray step
        distToEdge = map(ro);
        ro += rd * distToEdge;

        //grabs smallest distance for a cool glow and bloom effect
        smallest = smallest > distToEdge ? distToEdge : smallest;

        distTraveled += distToEdge;

        if(distToEdge < minDist)
        {
            break;
        }

        if(distTraveled > MAXDIST || i-1 > MAXSTEP){
            return vec3(.2,.1,.7)/mix(.2,.5,smallest);
        }




    }
    vec3 lightSource = vec3(sin(iTime),.0,cos(iTime)-.5);
    float lambert = dot(calcNormal(ro),lightSource)/distTraveled;

    return vec3(.4,.2,.6) * mix(.5,2.5,lambert);

}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // most of this initial stuf is from https://blog.demofox.org/2020/05/25/casual-shadertoy-path-tracing-1-basic-camera-diffuse-emissive/
    vec3 screen = vec3((fragCoord/iResolution.xy) * 2.0f - 1.0f, 1.0f);
    // correct for aspect ratio
    float aspectRatio = iResolution.x / iResolution.y;
    screen.y /= aspectRatio;

    Ray ray;

    ray.ro = vec3(.0,0.,.0);

    ray.rd = normalize(screen - ray.ro);

    vec3 col = getColor(ray.rd);


    // Output to screen
    fragColor = vec4(col,1.0);
}
